<script setup>
import { ref } from "vue";
import { post } from "../lib/api";
const file=ref(null), uploaded=ref(null), result=ref(null), busy=ref(false), error=ref("");
function select(event){file.value=event.target.files?.[0]||null;uploaded.value=null;result.value=null;error.value="";}
async function upload(){if(!file.value)return;busy.value=true;error.value="";try{if(file.value.size>1000000)throw new Error("文件请控制在 1 MB 以内");uploaded.value=await post("/api/evaluations/uploads",{name:file.value.name,content:await file.value.text()});}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function run(){busy.value=true;error.value="";try{result.value=await post(`/api/evaluations/uploads/${uploaded.value.id}/run`,{},{timeoutMs:600000});}catch(e){error.value=e.message;}finally{busy.value=false;}}
function template(){const blob=new Blob([JSON.stringify([{text:"我喜欢喝茶",expected:"semantic"},{text:"昨天我去了公园",expected:"episodic"}],null,2)],{type:"application/json"});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download="memory-dataset.json";a.click();URL.revokeObjectURL(url);}
</script>
<template><section class="le-section"><div><span class="le-kicker">BENCHMARK YOUR MEMORY</span><h2>{{ $t("带上你的数据，") }}<br/>{{ $t("检验记忆的表现。") }}</h2><p>{{ $t("上传自己的记忆分类数据集，查看系统如何理解每条信息。") }}</p><RouterLink to="/evaluations">{{ $t("打开评测中心 ↗") }}</RouterLink></div><div class="le-panel"><h3>{{ $t("上传数据集") }}</h3><p>{{ $t("JSON / JSONL · 最多 500 条 · 1 MB") }}</p><input type="file" accept=".json,.jsonl" :disabled="busy" :aria-label="$t('选择评测数据集')" @change="select"/><div class="le-actions"><button :disabled="!file || busy" @click="upload">{{ $t(busy?'处理中…':'上传并校验') }}</button><button class="le-secondary" :disabled="busy" @click="template">{{ $t("下载模板") }}</button></div><p class="le-help">{{ $t("每条包含 text 和 expected。标签支持 semantic、episodic、procedural、working、unknown。") }}</p><div v-if="uploaded" class="le-result"><strong>{{ uploaded.name }} · {{ uploaded.count }} 条已通过校验</strong><p>{{ $t("每次测试按原顺序运行前 20 条，结果单独保存。") }}</p><button :disabled="busy" @click="run">{{ $t(busy?'正在测试…':'开始分类评测') }}</button></div><p v-if="error" role="alert">{{ error }}</p><div v-if="result" class="le-result"><strong>准确率 {{ (result.accuracy*100).toFixed(1) }}%</strong><p>已测 {{ result.planned }}/{{ result.total }} 条 · 调用失败 {{ result.failed }} 条</p><details><summary>{{ $t("逐条结果") }}</summary><div v-for="(row,i) in result.results" :key="i" class="le-row"><p>{{ row.text }}</p><small>预期 {{ row.expected }} · 实际 {{ row.actual || '失败' }} · {{ $t(row.correct?'正确':'未命中') }}</small></div></details></div></div></section></template>
<style scoped>
.le-section{display:grid;grid-template-columns:1fr 1fr;gap:55px;align-items:center;padding:65px 0;border-top:1px solid #e6dfeb}.le-kicker{font-size:10px;letter-spacing:2px;color:#9a80aa}.le-section h2{font-size:36px;font-weight:550;line-height:1.45;margin:18px 0}.le-section p{font-size:12px;color:#8b8192;line-height:1.9;margin:12px 0}.le-section a{font-size:12px;color:#8e6caa}.le-panel{padding:27px;border:1px solid #ded6e6;border-radius:13px;background:#fff}.le-panel h3{font-size:17px}.le-panel input{max-width:100%;font-size:12px;margin:12px 0}.le-actions{display:flex;gap:10px}.le-panel button{padding:10px 14px;border:0;border-radius:7px;background:#28232e;color:#fff;cursor:pointer;font-size:12px}.le-panel button:disabled{opacity:.5;cursor:default}.le-panel .le-secondary{background:#f1edf5;color:#6c5b79}.le-help{font-size:10px!important}.le-result{border-top:1px solid #e6dfeb;margin-top:18px;padding-top:18px;font-size:12px}.le-row{padding:10px 0;border-bottom:1px solid #e6dfeb}.le-row small{color:#8b8192}@media(max-width:700px){.le-section{grid-template-columns:1fr;gap:20px;padding:40px 0}.le-section h2{font-size:29px}}
</style>
